import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import type { JobStatus } from './jobs.ts';

/** Opens the SQLite database shared by the server and worker processes and makes sure the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  initSchema(db);
  return db;
}

/** Idempotent schema creation: either process may run it first. */
function initSchema(db: DatabaseSync): void {
  transaction(db, () => {
    db.exec(`
      CREATE TABLE IF NOT EXISTS jobs (
        seq INTEGER PRIMARY KEY AUTOINCREMENT,
        id TEXT NOT NULL UNIQUE,
        input TEXT NOT NULL,
        steps INTEGER NOT NULL,
        fail_attempts INTEGER NOT NULL,
        status TEXT NOT NULL,
        attempts INTEGER NOT NULL DEFAULT 0,
        completed INTEGER NOT NULL DEFAULT 0,
        output TEXT,
        error TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        idem_key TEXT UNIQUE,
        payload TEXT,
        retry_at INTEGER NOT NULL DEFAULT 0
      );
      CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, retry_at, seq);
      CREATE TABLE IF NOT EXISTS worker_heartbeat (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        beat_at INTEGER NOT NULL
      );
    `);
  });
}

/** Runs `fn` inside a short IMMEDIATE transaction. Rolls back if `fn` throws. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is open; the original error is the one that matters
    }
    throw error;
  }
}

/** A row of the `jobs` table, using column names as stored. */
export interface JobRow {
  seq: number;
  id: string;
  input: string;
  steps: number;
  fail_attempts: number;
  status: JobStatus;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  idem_key: string | null;
  payload: string | null;
  retry_at: number;
}

const JOB_COLUMNS = `seq, id, input, steps, fail_attempts, status, attempts, completed, output, error,
  created_at, updated_at, idem_key, payload, retry_at`;

export function findJobById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`).get(id) as unknown as JobRow | undefined;
}

export function findJobByIdemKey(db: DatabaseSync, key: string): JobRow | undefined {
  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE idem_key = ?`).get(key) as unknown as JobRow | undefined;
}

/** All jobs, newest first (by insertion sequence). */
export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[];
}

export interface NewJobRow {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  idemKey: string | null;
  payload: string | null;
  now: string;
}

export function insertJob(db: DatabaseSync, job: NewJobRow): void {
  db.prepare(
    `INSERT INTO jobs (id, input, steps, fail_attempts, status, attempts, completed, output, error,
       created_at, updated_at, idem_key, payload, retry_at)
     VALUES (?, ?, ?, ?, 'queued', 0, 0, NULL, NULL, ?, ?, ?, ?, 0)`,
  ).run(job.id, job.input, job.steps, job.failAttempts, job.now, job.now, job.idemKey, job.payload);
}

// ---- Worker operations -------------------------------------------------------------------------

export interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  /** The attempt number this processing run counts as (1-based). */
  attempt: number;
}

/**
 * Picks the next job to process and marks it running. A job already `running` is an attempt
 * interrupted by a previous worker process: it is resumed with its counted attempt number and its
 * progress reset. Otherwise the oldest queued job whose retry deadline has passed is claimed and its
 * attempt counter incremented. Must run inside `transaction`.
 */
export function claimNextJob(db: DatabaseSync, now: number, nowIso: string): ClaimedJob | undefined {
  const row = db
    .prepare(
      `SELECT id, input, steps, fail_attempts, status, attempts FROM jobs
       WHERE status = 'running' OR (status = 'queued' AND retry_at <= ?)
       ORDER BY CASE WHEN status = 'running' THEN 0 ELSE 1 END, seq
       LIMIT 1`,
    )
    .get(now) as
    | { id: string; input: string; steps: number; fail_attempts: number; status: JobStatus; attempts: number }
    | undefined;
  if (!row) return undefined;

  if (row.status === 'running') {
    db.prepare(`UPDATE jobs SET completed = 0, updated_at = ? WHERE id = ?`).run(nowIso, row.id);
    return { id: row.id, input: row.input, steps: row.steps, failAttempts: row.fail_attempts, attempt: row.attempts };
  }

  const attempt = row.attempts + 1;
  db.prepare(
    `UPDATE jobs SET status = 'running', attempts = ?, completed = 0, output = NULL, error = NULL, updated_at = ?
     WHERE id = ?`,
  ).run(attempt, nowIso, row.id);
  return { id: row.id, input: row.input, steps: row.steps, failAttempts: row.fail_attempts, attempt };
}

export function recordProgress(db: DatabaseSync, id: string, completed: number, nowIso: string): void {
  db.prepare(`UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(completed, nowIso, id);
}

/** Returns a job to the queue after a transient failure, eligible again at `retryAt` (epoch ms). */
export function scheduleRetry(db: DatabaseSync, id: string, retryAt: number, nowIso: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, output = NULL, error = NULL, retry_at = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(retryAt, nowIso, id);
}

export function markFailed(db: DatabaseSync, id: string, attempts: number, error: string, nowIso: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', attempts = ?, completed = 0, output = NULL, error = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(attempts, error, nowIso, id);
}

export function markCompleted(db: DatabaseSync, id: string, steps: number, output: string, nowIso: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', completed = ?, output = ?, error = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(steps, output, nowIso, id);
}

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?)
     ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at`,
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare(`DELETE FROM worker_heartbeat WHERE id = 1`).run();
}

/** Epoch milliseconds of the worker's last heartbeat, if any. */
export function readHeartbeat(db: DatabaseSync): number | undefined {
  const row = db.prepare(`SELECT beat_at FROM worker_heartbeat WHERE id = 1`).get() as { beat_at: number } | undefined;
  return row?.beat_at;
}

