export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job shape returned by every endpoint that returns a job. */
export interface JobView {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const MAX_ATTEMPTS = 3;
export const TRANSIENT_FAILURE = 'transient failure';

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
/** Bodies larger than this are rejected; the limit only bounds memory use. */
export const MAX_BODY_BYTES = 64 * 1024;

export type ParseResult = { ok: true; job: NewJob; idempotencyKey: string | undefined } | { ok: false; fields: FieldError[] };

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isMediaTypeJson(contentType: string | undefined): boolean {
  if (contentType === undefined) return false;
  return contentType.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

function checkInteger(body: Record<string, unknown>, field: 'steps' | 'failAttempts', min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (!Object.hasOwn(body, field)) return fallback;
  const value = body[field];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

/**
 * Validates a job submission. Collects every problem it can find so the client sees all offending
 * fields at once.
 */
export function parseCreateRequest(contentType: string | undefined, bodyText: string, idempotencyKey: string | undefined): ParseResult {
  const fields: FieldError[] = [];
  let parsed: unknown;
  let haveBody = false;

  if (!isMediaTypeJson(contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    try {
      parsed = JSON.parse(bodyText);
      haveBody = true;
    } catch {
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
  }

  let job: NewJob = { input: '', steps: DEFAULT_STEPS, failAttempts: DEFAULT_FAIL_ATTEMPTS };
  if (haveBody && !isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
  } else if (haveBody && isPlainObject(parsed)) {
    const body = parsed;
    for (const key of Object.keys(body)) {
      if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
    }

    if (!Object.hasOwn(body, 'input')) {
      fields.push({ field: 'input', message: 'input is required' });
    } else if (typeof body.input !== 'string') {
      fields.push({ field: 'input', message: 'input must be a string' });
    } else if (body.input.length < 1 || body.input.length > 1000) {
      fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
    } else if (body.input.trim() === '') {
      fields.push({ field: 'input', message: 'input must not be only whitespace' });
    } else {
      job.input = body.input;
    }

    job.steps = checkInteger(body, 'steps', 1, 20, DEFAULT_STEPS, fields);
    job.failAttempts = checkInteger(body, 'failAttempts', 0, 5, DEFAULT_FAIL_ATTEMPTS, fields);
  }

  if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'must be 1 to 128 characters of letters, digits, "_" or "-"' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, job, idempotencyKey };
}

/** Canonical form of a submission after defaults: a fixed key order makes string equality mean payload equality. */
export function canonicalPayload(job: NewJob): string {
  return JSON.stringify({ input: job.input, steps: job.steps, failAttempts: job.failAttempts });
}

/** Converts a database row to the public job shape. Internal columns are not exposed. */
export function toJobView(row: JobRow): JobView {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

