import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import {
  findJobById,
  findJobByIdemKey,
  insertJob,
  listJobs,
  openDatabase,
  readHeartbeat,
  transaction,
  type JobRow,
} from './db.ts';
import { canonicalPayload, MAX_BODY_BYTES, parseCreateRequest, toJobView, type FieldError } from './jobs.ts';

/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_STALE_MS = 3_000;
const SHUTDOWN_GRACE_MS = 3_000;
const SHUTDOWN_HARD_MS = 5_000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields !== undefined) error.fields = fields;
  send(res, status, { error });
}

function notFound(res: ServerResponse): void {
  sendError(res, 404, 'not_found', 'No route matches this path.');
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  res.setHeader('allow', allowed.join(', '));
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allowed.join(' or ')}.`);
}

/** Reads the whole request body as text. Excess bytes are discarded and reported via `overflow`. */
function readBody(req: IncomingMessage): Promise<{ text: string; overflow: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let overflow = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        overflow = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), overflow }));
    req.on('error', reject);
    req.on('aborted', () => reject(new Error('request aborted')));
  });
}

function jobOrNotFound(res: ServerResponse, row: JobRow | undefined): void {
  if (row) send(res, 200, toJobView(row));
  else notFound(res);
}

type CreateOutcome = { status: 200 | 201; row: JobRow } | { status: 409 };

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, overflow } = await readBody(req);
  const header = req.headers['idempotency-key'];
  const idempotencyKey = header === undefined ? undefined : String(header);
  const parsed = overflow
    ? ({ ok: false, fields: [{ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` }] } as const)
    : parseCreateRequest(req.headers['content-type'], text, idempotencyKey);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', [...parsed.fields]);
    return;
  }

  const { job, idempotencyKey: key } = parsed;
  const payload = canonicalPayload(job);
  const outcome = transaction<CreateOutcome>(db, () => {
    if (key !== undefined) {
      const existing = findJobByIdemKey(db, key);
      if (existing) {
        return existing.payload === payload ? { status: 200, row: existing } : { status: 409 };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    insertJob(db, {
      id,
      input: job.input,
      steps: job.steps,
      failAttempts: job.failAttempts,
      idemKey: key ?? null,
      payload: key === undefined ? null : payload,
      now,
    });
    // Captured inside the transaction: the response describes the job as created (queued), even if
    // the worker claims it immediately afterwards.
    return { status: 201, row: findJobById(db, id)! };
  });

  if (outcome.status === 409) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, outcome.status, toJobView(outcome.row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const beat = readHeartbeat(db);
    const up = beat !== undefined && Date.now() - beat <= WORKER_STALE_MS;
    send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      send(res, 200, { jobs: listJobs(db).map(toJobView) });
      return;
    }
    if (method === 'POST') {
      await createJob(req, res);
      return;
    }
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    jobOrNotFound(res, findJobById(db, match[1]!));
    return;
  }

  notFound(res);
}

const server = createServer((req, res) => {
  handle(req, res).catch((error: unknown) => {
    console.error('request failed:', error);
    if (!res.headersSent && !res.writableEnded) {
      sendError(res, 500, 'internal_error', 'An unexpected error occurred.');
    } else if (!res.writableEnded) {
      res.end();
    }
  });
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  // Stop accepting connections; in-flight requests get a short grace period before being cut off.
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS).unref();
  setTimeout(() => process.exit(0), SHUTDOWN_HARD_MS);
}

for (const signal of ['SIGTERM', 'SIGINT'] as const) {
  process.on(signal, shutdown);
}

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

