    ? ({ ok: false, fields: [{ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` }] } as const)
    : parseCreateRequest(req.headers['content-type'], text, idempotencyKey);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', [...parsed.fields]);
    return;
  }

  const { job, idempotencyKey: key } = parsed;
  const payload = canonicalPayload(job);
  const outcome = transaction<CreateOutcome>(db, () => {
    if (key !== undefined) {
      const existing = findJobByIdemKey(db, key);
      if (existing) {
        return existing.payload === payload ? { status: 200, row: existing } : { status: 409 };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    insertJob(db, {
      id,
      input: job.input,
      steps: job.steps,
      failAttempts: job.failAttempts,
      idemKey: key ?? null,
      payload: key === undefined ? null : payload,
      now,
    });
    // Captured inside the transaction: the response describes the job as created (queued), even if
    // the worker claims it immediately afterwards.
    return { status: 201, row: findJobById(db, id)! };
  });

  if (outcome.status === 409) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, outcome.status, toJobView(outcome.row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const beat = readHeartbeat(db);
    const up = beat !== undefined && Date.now() - beat <= WORKER_STALE_MS;
    send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      send(res, 200, { jobs: listJobs(db).map(toJobView) });
      return;
    }
    if (method === 'POST') {
      await createJob(req, res);
      return;
    }
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    jobOrNotFound(res, findJobById(db, match[1]!));
    return;
  }

  notFound(res);
}

const server = createServer((req, res) => {
  handle(req, res).catch((error: unknown) => {
    console.error('request failed:', error);
    if (!res.headersSent && !res.writableEnded) {
      sendError(res, 500, 'internal_error', 'An unexpected error occurred.');
    } else if (!res.writableEnded) {
      res.end();
    }
  });
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  // Stop accepting connections; in-flight requests get a short grace period before being cut off.
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS).unref();
  setTimeout(() => process.exit(0), SHUTDOWN_HARD_MS);
}

for (const signal of ['SIGTERM', 'SIGINT'] as const) {
  process.on(signal, shutdown);
}

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

