import { setTimeout as sleep } from 'node:timers/promises';
import {
  claimNextJob,
  clearHeartbeat,
  markCompleted,
  markFailed,
  openDatabase,
  recordProgress,
  scheduleRetry,
  transaction,
  writeHeartbeat,
  type ClaimedJob,
} from './db.ts';
import { MAX_ATTEMPTS, TRANSIENT_FAILURE } from './jobs.ts';

/** Duration of one processing step. */
const STEP_MS = 100;
/** Delay before a failed attempt is retried. */
const RETRY_DELAY_MS = 500;
/** How often the worker proves it is alive. */
const HEARTBEAT_MS = 500;
/** Idle poll interval; also bounds how quickly a stop request is noticed while idle. */
const IDLE_POLL_MS = 100;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Records the failure of one attempt: schedules a retry, or fails the job after the last attempt. */
function failAttempt(job: ClaimedJob): void {
  const now = Date.now();
  const nowIso = new Date(now).toISOString();
  transaction(db, () => {
    if (job.attempt >= MAX_ATTEMPTS) {
      markFailed(db, job.id, job.attempt, TRANSIENT_FAILURE, nowIso);
    } else {
      scheduleRetry(db, job.id, now + RETRY_DELAY_MS, nowIso);
    }
  });
}

/** Runs one attempt of a job, one step at a time. Returns early without writing if asked to stop. */
async function runAttempt(job: ClaimedJob): Promise<void> {
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // left `running`; the next worker start recovers it
    if (job.attempt <= job.failAttempts) {
      // Simulated transient failure at the first step, before any progress is recorded.
      failAttempt(job);
      return;
    }
    recordProgress(db, job.id, step, new Date().toISOString());
  }
  markCompleted(db, job.id, job.steps, job.input.toUpperCase(), new Date().toISOString());
}

writeHeartbeat(db, Date.now());
const heartbeat = setInterval(() => {
  try {
    writeHeartbeat(db, Date.now());
  } catch (error) {
    console.error('heartbeat failed:', error);
  }
}, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const now = Date.now();
    const job = transaction(db, () => claimNextJob(db, now, new Date(now).toISOString()));
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    await runAttempt(job);
  } catch (error) {
    console.error('worker error:', error);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeat);
try {
  clearHeartbeat(db);
} finally {
  db.close();
  console.log('worker stopped');
  process.exit(0);
}

